//! Independent 100-digit depth certificates and critical and normal depth roots of
//! sediment-reduced culvert sections, on the quadrature geometry.
//!
//! Each pair holds the round-down and round-up binary64 bits of the exact value. A minimum
//! holds the round-down bits of a true minimum of `d r / ds` in `s = y / D'`. Sections
//! follow the order of `section_rows::SECTIONS`.

// Generated by `transcribe.py` in `resource/evidence/culvert-blockage/` from its frozen
// `depths.json`. Regenerate instead of editing.

/// SHA256 of the frozen `depths.json`.
pub const DEPTHS_SHA256: &str = "5937323aa561476fd254667e5adfa2cd84857818ed80b2f1364f0b0938dfb1c0";

pub const GRAVITY: u64 = 0x40239eb851eb851f;
pub const SLOPES: [u64; 2] = [0x3f50624dd2f1a9fc, 0x3f947ae147ae147b];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Class {
    Dry,
    BelowFloor,
    NearFloor,
    Free,
    NearCrown,
    AboveCrown,
    NearPeak,
    AboveCapacity,
    NonPositiveSlope,
}

/// `(s_j bits, round-down minimum of d r_n / ds on [2^-30, s_j])`.
pub type Rising = &'static [(u64, u64)];

/// Critical-slope certificate of one section.
#[derive(Clone, Copy, Debug)]
pub struct Critical {
    pub name: &'static str,
    pub minimum: u64,
    pub argmin: [u64; 2],
}

/// Normal-slope certificate of one section at one ratio. Box sections have no peak.
#[derive(Clone, Copy, Debug)]
pub struct Certificate {
    pub section: usize,
    pub roughness_ratio: u64,
    pub sign_changes: u32,
    pub peak: Option<[u64; 2]>,
    pub log_peak: Option<[u64; 2]>,
    pub rising: Rising,
    pub box_minimum: Option<u64>,
    pub log_crown: Option<[u64; 2]>,
}

#[derive(Clone, Copy, Debug)]
pub struct CriticalRow {
    pub section: usize,
    pub label: &'static str,
    pub discharge: u64,
    pub class: Class,
    pub root: Option<[u64; 2]>,
    pub relative_width: f64,
}

#[derive(Clone, Copy, Debug)]
pub struct NormalRow {
    pub section: usize,
    pub label: &'static str,
    pub discharge: u64,
    pub slope: u64,
    pub class: Class,
    pub root: Option<[u64; 2]>,
    pub relative_width: f64,
}

